// 1) Verifica el secreto compartido (el servidor lo envía en la cabecera x-webhook-secret).
// 2) Arma el mensaje para Telegram escapando HTML.
const item = $input.first().json;
const secret = $env.N8N_WEBHOOK_SECRET || '';
const received = (item.headers && item.headers['x-webhook-secret']) || '';
const authorized = secret.length >= 16 && received === secret;
const b = item.body || {};
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = b.createdAt ? new Date(b.createdAt).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'medium', timeStyle: 'short' }) : '';
const lines = [
  '🚀 <b>Nuevo interesado · AI Academy</b>',
  '',
  `<b>Nombre:</b> ${esc(b.name)}`,
  `<b>Correo:</b> ${esc(b.email)}`,
  `<b>Programa:</b> ${esc(b.programName || b.program)}`,
];
if (b.phone) lines.push(`<b>Teléfono:</b> ${esc(b.phone)}`);
lines.push('', `<b>Estado:</b> ${esc(b.status || 'Nuevo')}`, `<b>Recibido:</b> ${esc(when)} (hora de Colombia)`, `<b>ID:</b> <code>${esc(b.id)}</code>`);
if (b.adminUrl && /^https:\/\//.test(b.adminUrl)) lines.push('', `<a href="${esc(b.adminUrl)}">Abrir en el panel</a>`);
const valid = Boolean(b.id && b.name && b.email && (b.programName || b.program));
return [{ json: { authorized: authorized && valid, leadId: b.id || null, text: lines.join('\n') } }];
